-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_SH_TEASER.SNOWBOTS.T_CLOSE_SENTINEL
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Oslo'
  CONFIG = '{"autonomy": 3}'
  WHEN SYSTEM$STREAM_HAS_DATA('SDP_SH_TEASER.PUBLIC.STR_GL_JOURNAL')
AS
  CALL SDP_SH_TEASER.SNOWBOTS.SP_RUN_BOT('close-sentinel');

-- step 1 · Actuals landed: October GL + POS
SELECT SYSTEM$STREAM_HAS_DATA('SDP_SH_TEASER.PUBLIC.STR_GL_JOURNAL') OR SYSTEM$STREAM_HAS_DATA('SDP_SH_TEASER.PUBLIC.STR_POS_SALES');
-- step 2 · Completeness DMFs per feed
SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_SH_TEASER.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-10';
-- step 3 · Fallback: paged extract from Data Lake replica
CALL SDP_SH_TEASER.SNOWBOTS.SP_BACKFILL_FROM_DATALAKE('BC_GL', '2026-10', page_size => 250000);
-- step 4 · Reconcile: 3-way match + store-owner intercompany
CALL SDP_SH_TEASER.SNOWBOTS.SP_RECONCILE(period => '2026-10', tolerance_pct => 0.5);
-- step 5 · Guardrail: completeness ≥ 98% and TB difference = 0
SELECT MIN(completeness) >= 0.98 AND ABS(SUM(tb_diff)) = 0 FROM SDP_SH_TEASER.SNOWBOTS.V_CLOSE_STATUS WHERE period = '2026-10';
-- step 6 · Lock period 2026-10 (awaiting controller approval)
CALL SDP_SH_TEASER.PUBLIC.SP_LOCK_PERIOD('2026-10', approved_by => :approver);

