-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_SH_TEASER.SNOWBOTS.T_DRIVER_REFRESH
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Oslo'
  CONFIG = '{"autonomy": 4}'
AS
  CALL SDP_SH_TEASER.SNOWBOTS.SP_RUN_BOT('driver-refresh');

-- step 1 · Marketplace share refreshed
SELECT MAX(date) FROM FX_MARKETPLACE.PUBLIC.FX_RATES_DAILY;
-- step 2 · Upsert purchase-currency drivers
MERGE INTO SDP_SH_TEASER.PUBLIC.DIM_FX_RATE t USING (SELECT * FROM FX_MARKETPLACE.PUBLIC.FX_RATES_DAILY WHERE date = CURRENT_DATE) s ON t.pair = s.pair ...;
-- step 3 · Guardrail: daily move ≤ 3%
SELECT MAX(ABS(pct_change)) <= 0.03 FROM SDP_SH_TEASER.SNOWBOTS.V_FX_MOVES;
-- step 4 · Recalculate landed COGS for Nov–Dec
CALL SDP_SH_TEASER.PUBLIC.SP_RECALC(scope => 'COGS', from_period => '2026-11');
-- step 5 · One-line impact note
SELECT AI_COMPLETE('claude-sonnet-4-5', 'One sentence on: ' || :impact_json);

